API Gateway / Tokenization Proxy.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway / Tokenization Proxy container

Container_Boundary(api_gateway_tokenization_proxy_container, "API Gateway / Tokenization Proxy") {
    Component(Edge_Router_Component, "Edge Router Component", "Envoy Proxy", "Manages incoming traffic routing and TLS termination at the edge.")
    Component(Tokenization_Filter_Component, "Tokenization Filter Component", "Native Envoy C++/Lua configuration with Format-Preserving Encryption", "Performs low-latency stateless PAN tokenization without expensive HSM round-trips.")
    Component(Payload_Sanitizer_Component, "Payload Sanitizer Component", "Envoy Proxy filter", "Sanitizes and validates incoming payment authorization payloads.")
}

Rel(Edge_Router_Component, Payload_Sanitizer_Component, "Forwards traffic for payload validation")
Rel(Payload_Sanitizer_Component, Tokenization_Filter_Component, "Sends sanitized data for tokenization")

@enduml

Audit Log Sitter.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(Audit_Log_Sitter, "Audit Log Sitter") {
    Component(Kafka_Consumer_Component, "Kafka Consumer Component", "Rust, rdkafka", "Consumes real-time payment audit events from AWS MSK.")
    Component(Payload_Normalizer_Signer_Component, "Payload Normalizer & Signer Component", "Rust, AWS KMS", "Normalizes audit payloads and cryptographically signs them using AWS KMS.")
    Component(WORM_Storage_Batcher_Component, "WORM Storage Batcher Component", "Rust", "Batches normalized and signed payloads for persistent WORM storage.")
    Component(Resilience_DLQ_Router_Component, "Resilience & DLQ Router Component", "Rust, In-memory channel", "Handles failed or poisoned payloads and routes them to a Dead-Letter Queue.")
}

Rel(Kafka_Consumer_Component, Resilience_DLQ_Router_Component, "Passes failed/poisoned payloads", "In-memory channel")
Rel(Payload_Normalizer_Signer_Component, WORM_Storage_Batcher_Component, "Passes normalized signed payloads", "In-memory channel")

@enduml

Rule & Model Distribution Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("RuleModelDistributionService", "Rule & Model Distribution Service") {
    Component("ModelIngestionAPI", "Model Ingestion API", "Python / FastAPI + Pydantic", "Handles model ingestion, validation, and dry-run execution for updates.")
    Component("DistributionPublisher", "Distribution Publisher", "AWS SQS", "Publishes update notifications and rule hashes to the scoring engines.")
    Component("ArtifactStorageClient", "Artifact Storage Client", "AWS S3", "Fetches and stores versioned rules and machine learning models securely.")
}

Rel("ModelIngestionAPI", "ArtifactStorageClient", "Saves validated models and rules", "HTTPS")
Rel("ModelIngestionAPI", "DistributionPublisher", "Triggers update notifications", "AWS SQS")

@enduml
